	MOD    = 998244353
	MODF   = float64(MOD)
	SHRT   = float64(1 << 16)
	G      = 3.0
	MAXSIZ = 1 << 20
)

func fmod(x float64) float64 {
	return x - MODF*math.Trunc(x/MODF)
}

func modProd(a, b float64) float64 {
	t := math.Trunc(a / SHRT)
	return fmod(t*fmod(b*SHRT) + (a-SHRT*t)*b)
}

func fpow(a float64, b int) float64 {
	r := 1.0
	for b != 0 {
		if b&1 != 0 {
			r = modProd(r, a)
		}
		if b > 1 {
			a = modProd(a, a)
		}
		b >>= 1
	}
	return r
